        public Iterator<Map.Entry<K, V>> iterator() {
            return new SlotIterator<>(OpenAddressingHashMap.this);
        }

        @Override
        public boolean contains(Object o) {
            if (!(o instanceof Map.Entry<?, ?> e)) {
                return false;
            }
            Slot<K, V> slot = findSlot(e.getKey());
            return slot != null && Objects.equals(slot.value, e.getValue());
        }

        @Override
        public boolean remove(Object o) {
            if (!(o instanceof Map.Entry<?, ?> e)) {
                return false;
            }
            Slot<K, V> slot = findSlot(e.getKey());
            if (slot != null && Objects.equals(slot.value, e.getValue())) {
                OpenAddressingHashMap.this.remove(e.getKey());
                return true;
            }
            return false;
        }
    }

    /** Fail-fast iterator over live slots, supporting {@link #remove()}. */
    private static final class SlotIterator<K, V> implements Iterator<Map.Entry<K, V>> {
        private final OpenAddressingHashMap<K, V> map;
        private int expectedModCount;
        private int scan;            // next table index to examine
        private int nextIndex = -1;  // table index of nextSlot
        private int lastIndex = -1;  // table index of the last returned slot, for remove()
        private Slot<K, V> nextSlot;

        SlotIterator(OpenAddressingHashMap<K, V> map) {
            this.map = map;
            this.expectedModCount = map.modCount;
            advance();
        }

        private void advance() {
            Slot<K, V>[] table = map.table;
            while (scan < table.length) {
                Slot<K, V> slot = table[scan];
                if (slot != null && !slot.isTombstone()) {
                    nextIndex = scan;
                    nextSlot = slot;
                    scan++;
                    return;
                }
                scan++;
            }
            nextIndex = -1;
            nextSlot = null;
        }

        @Override
        public boolean hasNext() {
            return nextSlot != null;
        }

        @Override
        public Map.Entry<K, V> next() {
            if (map.modCount != expectedModCount) {
                throw new ConcurrentModificationException();
            }
            if (nextSlot == null) {
                throw new NoSuchElementException();
            }
            lastIndex = nextIndex;
            Slot<K, V> current = nextSlot;
            advance();
            return current;
        }

        @Override
        public void remove() {
            if (lastIndex < 0) {
                throw new IllegalStateException("next() has not been called, or remove() already called");
            }
            if (map.modCount != expectedModCount) {
                throw new ConcurrentModificationException();
            }
            map.table[lastIndex] = map.tombstone();
            map.size--;
            map.modCount++;
            expectedModCount = map.modCount; // stay consistent so iteration may continue
            lastIndex = -1;
        }
    }
}

