package hashmap;

import java.util.Arrays;
import java.util.ConcurrentModificationException;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.Objects;
import java.util.function.BiConsumer;

/**
 * A hash map implemented with <em>open addressing</em> and <em>linear probing</em>.
 *
 * <p>Keys and values are generic. {@code null} keys are not permitted; {@code null}
 * values are. Collisions are resolved by scanning forward (with wrap-around) to the
 * next free slot. Deleted slots are marked with <em>tombstones</em> so that probe
 * sequences are not broken; tombstones are reclaimed during insertion and cleared
 * on the next resize.
 *
 * <p>The backing table always has a power-of-two length, so the slot index is
 * computed with a fast bit-mask rather than a modulo. The table grows
 * automatically once the fraction of occupied slots (live entries plus
 * tombstones) exceeds the configured load factor, keeping operations amortized
 * {@code O(1)}.
 *
 * <p>The map is {@link Iterable} over its {@link Entry entries}, and also exposes
 * {@link #keys()} and {@link #values()} views; all three iterate in an unspecified
 * order and are <em>fail-fast</em> (a structural modification during iteration
 * triggers a {@link ConcurrentModificationException}). Equality and hash code are
 * value-based: two maps are equal when they hold the same key/value mappings.
 *
 * <p>This class is <strong>not</strong> thread-safe.
 *
 * @param <K> the type of keys maintained by this map
 * @param <V> the type of mapped values
 */
public final class OpenAddressingHashMap<K, V> implements Iterable<OpenAddressingHashMap.Entry<K, V>> {

    /** An immutable, read-only view of a single key/value mapping. */
    public interface Entry<K, V> {
        /** Returns this mapping's key. */
        K getKey();

        /** Returns this mapping's value (may be {@code null}). */
        V getValue();
    }

    /** Default initial capacity; must be a power of two. */
    private static final int DEFAULT_CAPACITY = 16;

    /** Default fraction of occupied slots that triggers a resize. */
    private static final double DEFAULT_LOAD_FACTOR = 0.5;

    /** A single table slot. A tombstone is a slot whose {@code key} is {@code null}. */
    private static final class Slot<K, V> implements Entry<K, V> {
        final K key;
        V value;

        Slot(K key, V value) {
            this.key = key;
            this.value = value;
        }

        boolean isTombstone() {
            return key == null;
        }

        @Override
        public K getKey() {
            return key;
        }

        @Override
        public V getValue() {
            return value;
        }
    }

    /** Shared tombstone marker; distinguishable from {@code null} (never used) slots. */
    private static final Slot<?, ?> TOMBSTONE = new Slot<>(null, null);

    private Slot<K, V>[] table;

    /** Number of live (non-tombstone) entries. */
    private int size;

    /** Live entries plus tombstones; the table is resized based on this figure. */
    private int occupiedSlots;

    /** Structural-modification counter backing fail-fast iteration. */
    private int modCount;

    private final double loadFactor;

    /** Creates an empty map with the default capacity and load factor. */
    public OpenAddressingHashMap() {
        this(DEFAULT_CAPACITY, DEFAULT_LOAD_FACTOR);
    }

    /**
     * Creates an empty map with the given initial capacity and the default load factor.
     *
     * @param initialCapacity a hint for the number of entries to hold without resizing
     * @throws IllegalArgumentException if {@code initialCapacity} is not positive
     */
    public OpenAddressingHashMap(int initialCapacity) {
        this(initialCapacity, DEFAULT_LOAD_FACTOR);
    }

    /**
     * Creates an empty map with the given initial capacity and load factor.
     *
     * @param initialCapacity a hint for the number of entries to hold without resizing
     * @param loadFactor      the fraction of occupied slots that triggers a resize,
     *                        in the open interval {@code (0, 1)}
     * @throws IllegalArgumentException if {@code initialCapacity} is not positive
     *                                  or {@code loadFactor} is not in {@code (0, 1)}
     */
    public OpenAddressingHashMap(int initialCapacity, double loadFactor) {
        if (initialCapacity <= 0) {
            throw new IllegalArgumentException("initialCapacity must be positive: " + initialCapacity);
        }
        if (!(loadFactor > 0.0 && loadFactor < 1.0) || Double.isNaN(loadFactor)) {
            throw new IllegalArgumentException("loadFactor must be in (0, 1): " + loadFactor);
        }
        this.table = newTable(tableSizeFor(initialCapacity));
        this.loadFactor = loadFactor;
    }

    /**
     * Associates {@code value} with {@code key}, replacing any previous mapping.
     *
     * @param key   the key, which must not be {@code null}
     * @param value the value to associate (may be {@code null})
     * @return the previous value for {@code key}, or {@code null} if there was none
     * @throws NullPointerException if {@code key} is {@code null}
     */
    public V put(K key, V value) {
        Objects.requireNonNull(key, "key must not be null");

        if (occupiedSlots + 1 > table.length * loadFactor) {
            resize(table.length * 2);
        }

        int firstTombstone = -1;
        int index = indexFor(key, table.length);
        while (true) {
            Slot<K, V> slot = table[index];
            if (slot == null) {
                // Reuse the earliest tombstone seen on the probe path, if any.
                int target = (firstTombstone >= 0) ? firstTombstone : index;
                if (firstTombstone < 0) {
                    occupiedSlots++;
                }
                table[target] = new Slot<>(key, value);
                size++;
                modCount++;
                return null;
            }
            if (slot.isTombstone()) {
                if (firstTombstone < 0) {
                    firstTombstone = index;
                }
            } else if (slot.key.equals(key)) {
                V previous = slot.value;
                slot.value = value;
                return previous; // value replacement is not a structural modification
            }
            index = next(index);
        }
    }

    /**
     * Returns the value associated with {@code key}, or {@code null} if none.
     *
     * <p>Note that a {@code null} return may also mean the key is mapped to
     * {@code null}; use {@link #containsKey(Object)} or {@link #getOrDefault} to
     * disambiguate.
     *
     * @param key the key to look up (may be {@code null}, which is never present)
     * @return the associated value, or {@code null} if the key is absent
     */
    public V get(K key) {
        Slot<K, V> slot = findSlot(key);
        return slot == null ? null : slot.value;
    }

    /**
     * Returns the value associated with {@code key}, or {@code defaultValue} if the
     * key is absent.
     *
     * @param key          the key to look up
     * @param defaultValue the value to return when the key is absent
     * @return the mapped value, or {@code defaultValue} if there is no mapping
     */
    public V getOrDefault(K key, V defaultValue) {
        Slot<K, V> slot = findSlot(key);
        return slot == null ? defaultValue : slot.value;
    }

    /**
     * Returns {@code true} if this map contains a mapping for {@code key}.
     *
     * @param key the key to test (may be {@code null}, which is never present)
     * @return whether the key is present
     */
    public boolean containsKey(K key) {
        return findSlot(key) != null;
    }

    /**
     * Removes the mapping for {@code key} if present.
     *
     * @param key the key whose mapping should be removed
     * @return the value that was associated with {@code key}, or {@code null} if absent
     */
    public V remove(K key) {
        if (key == null) {
            return null;
        }
        int index = indexFor(key, table.length);
        while (true) {
            Slot<K, V> slot = table[index];
            if (slot == null) {
                return null;
            }
            if (!slot.isTombstone() && slot.key.equals(key)) {
                V previous = slot.value;
                table[index] = tombstone();
                size--;
                modCount++;
                // occupiedSlots is unchanged: the tombstone still occupies the slot.
                return previous;
            }
            index = next(index);
        }
    }

    /** Returns the number of live entries in this map. */
    public int size() {
        return size;
    }

    /** Returns {@code true} if this map contains no entries. */
    public boolean isEmpty() {
        return size == 0;
    }

    /** Removes all entries, keeping the current table capacity. */
    public void clear() {
        Arrays.fill(table, null);
        size = 0;
        occupiedSlots = 0;
        modCount++;
    }

    /**
     * Performs {@code action} for every live entry, in unspecified order.
     *
     * @param action the action to apply to each key/value pair
     * @throws NullPointerException if {@code action} is {@code null}
     */
    public void forEach(BiConsumer<? super K, ? super V> action) {
        Objects.requireNonNull(action, "action must not be null");
        int expectedModCount = modCount;
        for (Slot<K, V> slot : table) {
            if (slot != null && !slot.isTombstone()) {
                action.accept(slot.key, slot.value);
            }
        }
        if (modCount != expectedModCount) {
            throw new ConcurrentModificationException();
        }
    }

    /**
     * Returns a fail-fast iterator over the live entries, in unspecified order.
     *
     * <p>The returned entries are read-only snapshots backed by the map's storage;
     * they do not support modification.
     */
    @Override
    public Iterator<Entry<K, V>> iterator() {
        return new SlotIterator<>(this);
    }

    /** Returns an {@link Iterable} view over the keys, in unspecified order. */
    public Iterable<K> keys() {
        return () -> mapped(Slot::getKey);
    }

    /** Returns an {@link Iterable} view over the values, in unspecified order. */
    public Iterable<V> values() {
        return () -> mapped(Slot::getValue);
    }

    /**
     * Compares this map with another for value-based equality: equal if and only if
     * the other object is an {@code OpenAddressingHashMap} with exactly the same
     * key/value mappings.
     */
    @Override
    public boolean equals(Object o) {
        if (o == this) {
            return true;
        }
        if (!(o instanceof OpenAddressingHashMap<?, ?> other)) {
            return false;
        }
        if (other.size != size) {
            return false;
        }
        @SuppressWarnings("unchecked")
        OpenAddressingHashMap<Object, Object> raw = (OpenAddressingHashMap<Object, Object>) other;
        for (Slot<K, V> slot : table) {
            if (slot != null && !slot.isTombstone()) {
                if (!raw.containsKey(slot.key) || !Objects.equals(slot.value, raw.get(slot.key))) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns a value-based hash code consistent with {@link #equals}. */
    @Override
    public int hashCode() {
        int h = 0; // order-independent sum of per-entry hashes
        for (Slot<K, V> slot : table) {
            if (slot != null && !slot.isTombstone()) {
                h += slot.key.hashCode() ^ (slot.value == null ? 0 : slot.value.hashCode());
            }
        }
        return h;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("{");
        boolean first = true;
        for (Entry<K, V> e : this) {
            if (!first) {
                sb.append(", ");
            }
            first = false;
            sb.append(e.getKey()).append('=').append(e.getValue());
        }
        return sb.append('}').toString();
    }

    // ----------------------------------------------------------------------
    // Internal helpers
    // ----------------------------------------------------------------------

    /** Locates the live slot for {@code key}, or {@code null} if absent. */
    private Slot<K, V> findSlot(K key) {
        if (key == null) {
            return null;
        }
        int index = indexFor(key, table.length);
        while (true) {
            Slot<K, V> slot = table[index];
            if (slot == null) {
                return null;
            }
            if (!slot.isTombstone() && slot.key.equals(key)) {
                return slot;
            }
            index = next(index);
        }
    }

    /** Computes the home slot for {@code key} in a table of {@code length} slots. */
    private static int indexFor(Object key, int length) {
        int h = key.hashCode();
        h ^= (h >>> 16); // spread high bits into low bits to reduce clustering
        return h & (length - 1);
    }

    /** Returns the next slot index, wrapping around the power-of-two table. */
    private int next(int index) {
        return (index + 1) & (table.length - 1);
    }

    @SuppressWarnings("unchecked")
    private Slot<K, V> tombstone() {
        return (Slot<K, V>) TOMBSTONE;
    }

    @SuppressWarnings("unchecked")
    private Slot<K, V>[] newTable(int capacity) {
        return (Slot<K, V>[]) new Slot[capacity];
    }

    /** Rebuilds the table at {@code newCapacity}, dropping tombstones. */
    private void resize(int newCapacity) {
        Slot<K, V>[] old = table;
        table = newTable(newCapacity);
        occupiedSlots = 0;
        // size is unchanged: every live slot is re-placed exactly once.
        for (Slot<K, V> slot : old) {
            if (slot != null && !slot.isTombstone()) {
                placeKnownAbsent(slot);
                occupiedSlots++;
            }
        }
    }

    /**
     * Places a slot known to be unique into the current table. Used only by
     * {@link #resize}, where there are no duplicates and no tombstones, so the
     * first {@code null} encountered is the destination.
     */
    private void placeKnownAbsent(Slot<K, V> slot) {
        int index = indexFor(slot.key, table.length);
        while (table[index] != null) {
            index = next(index);
        }
        table[index] = slot;
    }

    /** Rounds {@code cap} up to the nearest power of two (at least 1). */
    private static int tableSizeFor(int cap) {
        int n = -1 >>> Integer.numberOfLeadingZeros(cap - 1);
        return (n < 0) ? 1 : n + 1;
    }

    /** Builds a fail-fast iterator that projects each live slot through {@code projection}. */
    private <T> Iterator<T> mapped(java.util.function.Function<Slot<K, V>, T> projection) {
        SlotIterator<K, V> slots = new SlotIterator<>(this);
        return new Iterator<>() {
            @Override
            public boolean hasNext() {
                return slots.hasNext();
            }

            @Override
            public T next() {
                return projection.apply(slots.nextSlot());
            }
        };
    }

    /** Fail-fast iterator over live slots, shared by the entry/key/value views. */
    private static final class SlotIterator<K, V> implements Iterator<Entry<K, V>> {
        private final OpenAddressingHashMap<K, V> map;
        private final int expectedModCount;
        private int index;
        private Slot<K, V> nextSlot;

        SlotIterator(OpenAddressingHashMap<K, V> map) {
            this.map = map;
            this.expectedModCount = map.modCount;
            this.nextSlot = advance();
        }

        private Slot<K, V> advance() {
            while (index < map.table.length) {
                Slot<K, V> slot = map.table[index++];
                if (slot != null && !slot.isTombstone()) {
                    return slot;
                }
            }
            return null;
        }

        @Override
        public boolean hasNext() {
            return nextSlot != null;
        }

        @Override
        public Entry<K, V> next() {
            return nextSlot();
        }

        Slot<K, V> nextSlot() {
            if (map.modCount != expectedModCount) {
                throw new ConcurrentModificationException();
            }
            if (nextSlot == null) {
                throw new NoSuchElementException();
            }
            Slot<K, V> current = nextSlot;
            nextSlot = advance();
            return current;
        }
    }
}

